package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenDivisionTest {
 @Test public void allBoundaryQuotientsAndRemaindersUsePublicNumbers(){assertEquals(1000001000000L,BoundedWholeDivision.count(1000000));assertArrayEquals(new int[]{0,1},BoundedWholeDivision.at(1000000,0));assertArrayEquals(new int[]{1000000,1000000},BoundedWholeDivision.at(1000000,BoundedWholeDivision.count(1000000)-1));for(int[] v:new int[][]{{0,1},{0,1000000},{1000000,1},{1000000,1000000},{1000000,999999},{17,1000000},{101001,99},{999999,97}}){Question q=BoundedWholeDivision.make(v[0],v[1]);q.answers=new String[]{"poison","poison"};q.expression="poison";for(List<String> answer:List.of(List.of(""+(v[0]/v[1]),""+(v[0]%v[1])),List.of(v[0]/v[1]+".0",v[0]%v[1]+"/1")))assertTrue(new Checker().check(q,List.of(),answer).correct());assertEquals(1,new Checker().check(q,List.of(),List.of(""+(v[0]/v[1]),""+(v[0]%v[1]+1))).index);assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(HelpPlan.forQuestion(q).size()>=8);}}
 @Test public void normalSupplyKeepsLowerGradesAndBothRemainderKinds(){var l=GlobalCurriculum.limits("na-nied-primary-2024-v1","remainder",7);assertTrue(BoundedWholeDivision.selected("remainder",l));assertFalse(BoundedWholeDivision.selected("remainder",GlobalCurriculum.limits("na-nied-primary-2024-v1","remainder",5)));Generator g=new Generator(new Random(308));List<String>recent=new ArrayList<>();Set<Boolean>exact=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next("remainder",recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertEquals(BoundedWholeDivision.KIND,q.kind);assertTrue(l.allows(q));String[]s=q.prompt.split(" ÷ ");int a=Integer.parseInt(s[0]),b=Integer.parseInt(s[1]);exact.add(a%b==0);assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of(true,false),exact);}
}
